def scope_stores(scope_id):
    return STORES if scope_id == SCOPE_ID else APPROVED_STORES if scope_id == EXPANDED_SCOPE_ID else {}


def validate_scope(scope_id, store_ids):
    allowed = scope_stores(scope_id)
    return (type(store_ids) is list and 1 <= len(store_ids) <= len(allowed)
            and all(type(s) is str and s in allowed for s in store_ids)
            and len(set(store_ids)) == len(store_ids))


def scope_for_stores(store_ids):
    if validate_scope(SCOPE_ID,store_ids):return SCOPE_ID
    if validate_scope(EXPANDED_SCOPE_ID,store_ids):return EXPANDED_SCOPE_ID
    raise ValueError('fleet_scope_invalid')


def interleaved_stores(store_ids):
    """Deterministic city round-robin; no city is drained before the next."""
    if not validate_scope(EXPANDED_SCOPE_ID,store_ids):raise ValueError('fleet_scope_invalid')
    groups={city:sorted((s for s in store_ids if APPROVED_STORES[s]['city']==city),key=int)
            for city in (*CITIES,*ADDITIONAL_CITIES)}
    return [group[index] for index in range(max(map(len,groups.values())))
            for group in groups.values() if index<len(group)]
